[
 'slug' => 'in-camera-basics', 'title' => 'In-Camera Basics: Exposure, Framing and Focus', 'level' => 'Beginner', 'category' => 'In-camera basics', 'duration' => '3 hours', 'featured' => 1,
 'summary' => 'Learn to get a clean, well-exposed, well-composed picture straight out of the camera — before any editing.',
 'description' => 'Most problems in a film cannot be fixed later. This course teaches the key camera skills every filmmaker needs: how exposure works, how to frame a shot, how to control focus and how to keep the picture steady.',
 'outcomes' => "Explain aperture, shutter speed and ISO and how they work together\nChoose correct exposure settings for a scene\nFrame shots using standard shot sizes and composition rules\nControl focus and depth of field\nKeep footage steady and correctly white-balanced",
 'lessons' => [
  ['Know your camera', 12, "<p>Every camera — a cinema camera, a DSLR or a phone — has three things in common: a <strong>sensor</strong> that records light, a <strong>lens</strong> that shapes it and <strong>controls</strong> that decide how much light reaches the sensor.</p><h4>Set these first, every time</h4><ul><li><strong>Resolution and frame rate:</strong> choose them before you shoot and keep them the same for the whole project. 24 or 25 frames per second gives the familiar film look; 50 or 60 gives smooth slow motion.</li><li><strong>Shooting mode:</strong> learn manual mode. Automatic modes change settings in the middle of a shot, which ruins footage.</li><li><strong>Card and battery:</strong> format the card in the camera, check it has space and carry spare batteries.</li></ul><p>Before a shoot, always record a short test clip and watch it back on a larger screen.</p>"],
  ['The exposure triangle', 18, "<p>Exposure is how bright or dark the picture is. Three settings control it:</p><ul><li><strong>Aperture (f-stop):</strong> the size of the lens opening. A small f-number (f/1.8) lets in more light and gives a blurry background; a large number (f/11) lets in less light and keeps more of the scene sharp.</li><li><strong>Shutter speed:</strong> how long the sensor collects light for each frame. For natural-looking motion in video, set it to about double your frame rate (for example 1/50 at 25 fps). This is called the 180-degree shutter rule.</li><li><strong>ISO:</strong> the sensor’s sensitivity. Higher ISO brightens the picture but adds grain (noise). Use the lowest ISO that gives a good exposure.</li></ul><h4>Fixing brightness without ruining the look</h4><p>Because shutter speed is fixed for video, you change brightness with aperture, ISO and <strong>ND (neutral density) filters</strong>. An ND filter works like sunglasses for the lens, letting you keep a wide aperture in bright sun.</p>"],
  ['Framing and composition', 20, "<p>Directors and cinematographers describe shots by how much of the subject they show:</p><ul><li><strong>Wide / establishing shot:</strong> shows the place and where people are in it.</li><li><strong>Medium shot:</strong> a person from about the waist up — good for conversation.</li><li><strong>Close-up:</strong> the face, for emotion.</li><li><strong>Extreme close-up:</strong> a detail such as eyes or hands.</li></ul><h4>Composition tools</h4><ul><li><strong>Rule of thirds:</strong> imagine the frame split into a 3×3 grid and place the subject on a line or intersection.</li><li><strong>Headroom:</strong> leave a small space above the head; do not cut through the top of the head or leave a large gap.</li><li><strong>Lead room (looking room):</strong> leave space in front of a person who is looking or moving sideways.</li><li><strong>Leading lines and depth:</strong> use roads, fences or doorways, and put something in the foreground to add depth.</li></ul>"],
  ['Focus, depth of field and a steady shot', 18, "<p><strong>Depth of field</strong> is how much of the picture, from near to far, is sharp. It is shallower with a wide aperture, a longer lens, or when the camera is close to the subject.</p><ul><li>Focus on the <strong>eyes</strong> of a person.</li><li>Use <strong>focus peaking</strong> or magnify the image to check focus; never trust the small screen alone.</li><li>If the subject moves, either use continuous autofocus carefully or practise pulling focus by hand.</li></ul><h4>Keeping it steady and natural</h4><ul><li>Use a <strong>tripod</strong> for interviews and still shots. Handheld movement should be deliberate, not accidental.</li><li>Hold the camera close to your body, bend your knees and walk heel-to-toe for smoother moves.</li><li>Set <strong>white balance</strong> manually (for example about 5600K in daylight) so colours stay the same from shot to shot.</li></ul>"],
 ],
 'questions' => [
  ['Which setting controls the size of the lens opening?', ['ISO', 'Aperture', 'Shutter speed', 'White balance'], 1, 'Aperture (the f-stop) is the size of the opening in the lens.'],
  ['At 25 frames per second, which shutter speed follows the 180-degree rule?', ['1/25', '1/50', '1/500', '1/1000'], 1, 'Double the frame rate: about 1/50 at 25 fps.'],
  ['What is the main downside of a very high ISO?', ['Blurry motion', 'More grain (noise) in the picture', 'A shallower depth of field', 'Wrong colours'], 1, 'High ISO brightens the image but adds noise.'],
