[
 'slug' => 'smartphone-filmmaking', 'title' => 'Smartphone Filmmaking Essentials', 'level' => 'Beginner', 'category' => 'In-camera basics', 'duration' => '2.5 hours', 'featured' => 1,
 'summary' => 'Make professional-looking films with the phone already in your pocket: settings, light, sound and storage.',
 'description' => 'A modern phone can shoot excellent video. This course covers the settings and habits that separate a polished phone film from a casual clip.',
 'outcomes' => "Set up a phone for filming (resolution, frame rate, lens, focus and exposure lock)\nUse natural light and simple reflectors well\nRecord clean sound with an external microphone\nHold, mount and move the phone steadily\nManage storage, batteries and backups on a shoot",
 'lessons' => [
  ['Set up your phone for filming', 12, "<ul><li><strong>Turn the phone sideways (landscape)</strong> for films that will be watched on TV, computers and YouTube.</li><li><strong>Clean the lens</strong> with a soft cloth — a greasy lens makes soft, hazy pictures.</li><li><strong>Choose one resolution and frame rate:</strong> 1080p at 25 or 30 fps is a safe choice and uses less storage than 4K.</li><li><strong>Lock exposure and focus</strong> (tap and hold on the screen) so the picture does not pump up and down.</li><li><strong>Switch on airplane mode</strong> and do-not-disturb so calls do not interrupt a take.</li><li>Use the <strong>main (rear) camera</strong>, not the selfie camera, whenever you can; it has the better sensor.</li></ul>"],
  ['Light for phone cameras', 14, "<p>Phone sensors are small, so they need good light and struggle in the dark.</p><ul><li>Shoot in the <strong>early morning or late afternoon</strong> when the sun is soft. Midday sun makes harsh shadows under the eyes.</li><li>Put the subject so that light falls on the <strong>face</strong>; never film a person with a bright window or sky directly behind them unless you want a silhouette.</li><li>Use a <strong>reflector</strong> (white card, foil on cardboard or a white sheet) to bounce light into shadows.</li><li>Indoors, sit people facing a window for soft, flattering light.</li></ul>"],
  ['Capture clean sound', 16, "<p>Audiences forgive a slightly soft picture, but not bad sound. A phone’s built-in microphone records everything, including wind and echoes.</p><ul><li>Use a <strong>lavalier (clip-on) microphone</strong> for interviews and dialogue, placed on the chest, about a fist-width from the mouth.</li><li>Use <strong>headphones</strong> to check the sound while recording.</li><li>Shoot in a <strong>quiet place</strong>; turn off fans and radios.</li><li>Record 30 seconds of <strong>room tone</strong> (silence) in each location for the editor.</li><li>Use a windshield (a foam or furry cover) outdoors.</li></ul>"],
  ['Steady shots, storage and backup', 14, "<ul><li>Use a <strong>small tripod or a gimbal</strong>, or rest the phone against a solid object.</li><li>If handheld, use both hands, elbows tucked in, and move slowly.</li><li>Keep at least <strong>20% of storage free</strong> and charge the battery fully before a shoot; carry a power bank.</li><li><strong>Back up the same day:</strong> copy footage to a computer and a second drive. Never delete from the phone until you have two copies.</li><li>Name files and folders by date and scene so you can find them in editing.</li></ul>"],
 ],
 'questions' => [
  ['For a film to be watched on TV and YouTube, how should you hold the phone?', ['Vertically', 'Horizontally (landscape)', 'Upside down', 'It does not matter'], 1, 'Landscape matches the shape of screens.'],
  ['Why lock exposure and focus?', ['To save storage', 'To stop the picture changing during a shot', 'To record in 4K', 'To improve sound'], 1, 'Locking prevents hunting and brightness shifts.'],
  ['What is the best time of day for soft, flattering natural light?', ['Midday', 'Early morning or late afternoon', 'Only at night', 'During a storm'], 1, 'Low sun is softer and more flattering.'],
  ['What does a reflector do?', ['Records sound', 'Bounces light into shadows', 'Stabilises the phone', 'Increases resolution'], 1, 'It redirects light onto the subject.'],
  ['Which accessory improves dialogue sound most?', ['A bigger screen', 'A clip-on lavalier microphone', 'A phone case', 'A screen protector'], 1, 'A close microphone records cleaner voices.'],
  ['What is “room tone”?', ['Background music', 'A recording of the location’s silence', 'A camera setting', 'A type of lens'], 1, 'Room tone helps editors fill gaps smoothly.'],
