[
 'slug' => 'acting-for-screen-foundations', 'title' => 'Acting for Screen: Foundations', 'level' => 'Beginner', 'category' => 'Acting', 'duration' => '3 hours', 'featured' => 1,
 'summary' => 'Start your screen-acting journey: listening, truthful behaviour, objectives, working with the camera and set etiquette.',
 'description' => 'Screen acting is different from stage acting: the camera sees everything, so honesty and stillness matter. This course gives new actors the core skills and habits for film and TV sets.',
 'outcomes' => "Explain how screen acting differs from stage acting\nListen and react truthfully\nPlay objectives and actions in a scene\nHit marks and keep eyelines correct\nRepeat movements for continuity and behave professionally on set",
 'lessons' => [
  ['Screen versus stage', 14, "<p>On stage the audience may sit far away, so actors use big voice and movement. On screen the camera can be a few inches from your face, so the performance can be <strong>small, real and detailed</strong>.</p><ul><li>You do not need to “show” emotion — <strong>think and listen</strong>, and let it appear in your eyes.</li><li>Stillness is powerful. Do not add gestures just to fill time.</li><li>The camera is the audience: act to your scene partner, not to the lens (unless the director says so).</li></ul>"],
  ['Listening, reacting and objectives', 18, "<p>Good acting is mostly <strong>listening</strong>. A scene comes alive when you really hear what the other person says and let it change you.</p><ul><li>Know your <strong>objective</strong>: what do you want from the other character in this scene?</li><li>Play an <strong>action</strong> to get it: persuade, comfort, challenge, avoid, charm.</li><li>React honestly. Your face and body show your thoughts; do not plan reactions in advance.</li></ul><p><strong>Practise:</strong> read a scene with a friend. Each of you decides on an objective and tries to get it without telling the other.</p>"],
  ['Marks, eyelines and continuity', 18, "<ul><li><strong>Marks:</strong> pieces of tape on the floor showing where to stand so you are in focus and in the light. Learn to find your mark without looking down.</li><li><strong>Eyeline:</strong> where you look. In close-ups you often look slightly to one side of the lens at the other actor (or at a stand-in). Do not look into the lens unless told to.</li><li><strong>Continuity:</strong> repeat the same actions, props and movements in every take and every angle (for example, take a sip on the same word). Remember which hand holds the cup.</li><li><strong>Matching energy:</strong> keep the same level of energy from take to take.</li></ul>"],
  ['On set: preparation and professionalism', 14, "<ul><li>Learn your lines well enough that you can <strong>forget them</strong> and play the moment.</li><li>Arrive early, be kind to every crew member and keep quiet when the crew shout “Rolling!” or “Quiet on set!”.</li><li>Take direction without arguing; ask questions at the right moment.</li><li>Look after your voice, body and sleep. Eat and drink water.</li><li>Always protect your <strong>boundaries</strong>: if anything makes you uncomfortable, say so to the director, assistant director or producer.</li></ul>"],
 ],
 'questions' => [
  ['Screen acting is usually…', ['Larger and louder than stage acting', 'Smaller, real and detailed', 'Done without listening', 'Only done in close-up'], 1, 'The camera picks up small details.'],
  ['Where should you normally look when acting in a scene?', ['Into the camera lens', 'At your scene partner (or the marked eyeline)', 'At the floor', 'At the director'], 1, 'Unless told otherwise, avoid looking into the lens.'],
  ['What is an “objective”?', ['What your character wants in the scene', 'Your costume', 'Your marks', 'The camera type'], 0, 'It is what the character wants.'],
