[
 'slug' => 'acting-for-screen-craft-and-audition', 'title' => 'Acting for Screen: Craft and Auditions', 'level' => 'Intermediate', 'category' => 'Acting', 'duration' => '3 hours',
 'summary' => 'Go deeper: script breakdown, subtext, working on emotion safely, self-tapes and audition skills.',
 'description' => 'For actors who know the basics and want to prepare roles more deeply, record strong self-tape auditions and work professionally.',
 'outcomes' => "Break down a script and find subtext\nPrepare emotional moments in a healthy way\nRecord a clear, professional self-tape\nBehave professionally in auditions and on set\nBuild a simple actor’s portfolio",
 'lessons' => [
  ['Script breakdown and subtext', 18, "<p>Read the whole script, not only your scenes. For your character, list:</p><ul><li><strong>Facts:</strong> age, job, family, where they live, what they say about themselves.</li><li><strong>Relationships:</strong> what each person means to your character.</li><li><strong>Arc:</strong> how the character changes from the start to the end.</li></ul><p><strong>Subtext</strong> is what the character really means beneath the words. “Are you leaving?” might mean “Please stay.” Decide the subtext for key lines and play it through your actions and eyes.</p>"],
  ['Emotion, imagination and wellbeing', 16, "<ul><li>Use your <strong>imagination</strong> and the circumstances of the scene (“what if this were happening to me?”) to connect to emotion.</li><li>Do not push for tears. Focus on the objective; emotion often follows.</li><li>Create a quick <strong>warm-up</strong> (breath, shoulders, face) and a <strong>cool-down</strong> after intense scenes.</li><li>Keep a clear line between you and the character. Talk to someone you trust if a role is affecting you.</li></ul>"],
  ['Self-tapes and auditions', 20, "<ul><li><strong>Read the casting brief</strong> and follow it exactly (slate, length, what to read).</li><li><strong>Frame:</strong> head and shoulders or mid-shot, steady camera, plain background.</li><li><strong>Light:</strong> face a window or lamp so your face is evenly lit; avoid shadows.</li><li><strong>Sound:</strong> quiet room, phone close enough, test first.</li><li>Have a reader off-camera, just next to the lens, who reads quietly.</li><li>Do several takes and send your <strong>best</strong>; label the file with your name and role.</li><li>Arrive early to in-person auditions, be polite to everyone and take direction without defending.</li></ul>"],
  ['Professional habits and portfolio', 14, "<ul><li>Keep a simple <strong>profile</strong>: photo, contact details, short bio, training and credits.</li><li>Build a short <strong>showreel</strong> of your best 1–2 minutes of work; never include scenes you have no permission to use.</li><li>Read contracts and ask about pay, hours, nudity or intimate scenes and safety <strong>before</strong> you agree.</li><li>Be punctual, prepared and kind — directors rehire reliable people.</li></ul>"],
 ],
 'questions' => [
  ['What is subtext?', ['What the character really means beneath the words', 'Text printed at the bottom of the screen', 'The title of a scene', 'A camera note'], 0, 'Subtext is the meaning under the words.'],
  ['For a self-tape, what should you do first?', ['Read and follow the casting brief', 'Choose a random scene', 'Add effects', 'Send it without checking'], 0, 'Follow the brief exactly.'],
  ['A good self-tape frame is usually…', ['Head and shoulders or mid-shot', 'A very wide shot', 'An extreme close-up of an eye', 'A shot from the floor'], 0, 'It shows the face and upper body clearly.'],
  ['Where should the reader be during a self-tape?', ['Off-camera, close to the lens', 'On camera', 'In another room', 'Not needed'], 0, 'It helps the eyeline.'],
